const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={cases:[],integration:{}},current=null,role='employee',busy=false,invite='',pendingFile=null,dirty=false;
const preparationErrors={invalid_checklist:'Add a short evidence or follow-up note (10–400 characters).',checklist_owner_only:'Only the person responsible for this preparation item can update it.',invalid_profile:'Check the situation fields. Use a stay-status label such as E-7-1, or leave it empty.',situation_required:'Save your situation before running the AI check.',invalid_company_check:'Complete the verification placeholders and record at least 15 characters for each company check.',preparation_incomplete:'Complete the situation, company checks and preparation items before approval. A follow-up needs a written next step.',employee_not_joined:'The employee must join this case before company files can be uploaded.',document_owner_only:'Only the role responsible for this document can replace or remove it.'};
