const errors={correction_quote_mismatch:'The corrected value must be supported by the exact source text you entered.',guidance_outdated:'The facts or situation changed. These are checked actions; regenerate the AI draft when ready.',situation_note_limit:'This case has reached its situation-note history limit.',invalid_situation_note:'Add a situation note or select a start-date update. Use a valid date and omit identifiers.',invalid_correction:'Use a valid original value, source quote and reason. Dates must be valid calendar dates.',correction_evidence_required:'Check the original and explain the correction in at least 10 characters.',correction_wrong_source:'Select a current source page for this type of fact.',correction_unchanged:'The value is unchanged. Select the field that was misread.',correction_limit:'This version has reached its correction limit.',provider_invalid_json:'The AI response could not be read. Your files are saved; you can submit again when ready.',provider_network:'The AI service could not be reached. Your files are saved; try again when the connection is restored.',provider_invalid_guidance:'The AI message did not pass its checks. The document findings remain available for your reviewer.',analysis_interrupted:'The previous analysis was interrupted. Your files are saved and can be submitted again.',guidance_failed:'The AI message was unavailable. The document findings remain available for your reviewer.',auth:'Sign in to access your cases.',origin:'Reload this page and try again.',revision_conflict:'This case changed in another window. Refresh before continuing.',use_employee_account:'Open the invitation while signed in to the employee account. Use the separate demo to try both views yourself.',invalid_invite:'This invitation has expired or was already used. Ask the reviewer for a new link.',ai_not_configured:'Live AI or file storage is not configured. Your files remain saved.',file_storage:'File storage is not connected yet.',daily_limit:'The daily AI request limit has been reached. Your files remain saved; try again after the KST daily reset.',provider_auth:'The AI provider rejected the server credential. Contact the site owner.',provider_billing:'The AI provider reports a billing or credit issue.',provider_limit:'The provider is busy or rate-limited. Try again later.',provider_timeout:'The AI request timed out. Your files remain saved. Retry when ready.',provider_ungrounded:'The extracted information could not be matched to its cited text. No result was accepted. Check the page quality and retry.',provider_invalid_output:'The AI returned an invalid result. No result was accepted.',provider_invalid_date:'A reported date could not be validated. No result was accepted.',provider_invalid_status:'The reported stay status could not be validated.',provider_incomplete:'The selected model returned an incomplete or unexpected response.',provider_rejected:'The AI provider rejected the request. Your files remain saved.',page_limit:'Use up to 12 pages per file and 16 pages per case.',too_large:'This upload is too large. Use files under 10 MB.',unsupported_file:'Use a genuine PDF, JPEG or PNG file.',invalid_file:'Choose a PDF, JPEG or PNG under 10 MB.',resolution_required:'Record how you checked each remaining finding and any unresolved external next step before approving.',review_required:'Complete all three review confirmations.',invalid_message:'Write a clear English preparation message, without identifiers, links or a claim of immigration approval.',processing:'Analysis is already running. Refresh to see progress.',not_submittable:'Upload a new or corrected file before running analysis again.',version_limit:'This case has reached its 10-version limit.',case_storage_limit:'This case has reached its file storage limit.',not_reviewable:'This version is not ready for a reviewer decision.'};
const notice=(text,type='')=>$('#notice').innerHTML=text?`<div class="notice ${esc(type)}">${esc(text)}</div>`:'';
async function api(path='',body,method='POST'){const r=await fetch('/api/intake'+path,body===undefined?{cache:'no-store'}:{method,headers:body instanceof FormData?{}:{'content-type':'application/json'},body:body instanceof FormData?body:JSON.stringify(body)});const j=await r.json();if(r.status===401){signedOut=true;current=null;data={cases:[],companies:[],integration:{}};}if(j.case){current=j.case;data.cases=data.cases.filter(c=>c.id!==current.id);data.cases.unshift(current);}if(!r.ok)throw Object.assign(new Error(companyErrors[j.code]||preparationErrors[j.code]||errors[j.code]||`Could not complete this action (${j.code||r.status}).`),{code:j.code});return j;}
async function action(fn,message){if(busy)return;const formState=[...document.querySelectorAll('#content input:not([type=file]),#content textarea,#content select')].filter(e=>e.id).map(e=>({id:e.id,value:e.value,checked:e.checked}));let failed=false;busy=true;notice(message||'Saving…','busy');document.querySelectorAll('#content button,#home,#refresh').forEach(b=>b.disabled=true);try{await fn();dirty=false;notice('');}catch(e){failed=true;notice(e.message,'error');}finally{busy=false;render();if(failed){for(const saved of formState){const el=document.getElementById(saved.id);if(el){el.value=saved.value;if(saved.id==='correction-target')el.dispatchEvent(new Event('change'));el.closest('details')?.setAttribute('open','');if('checked'in el)el.checked=saved.checked;}}}$('#home').disabled=false;$('#refresh').disabled=false;}}
async function load(){const j=await api();signedOut=false;data=j;if(!initialCompanyChosen){initialCompanyChosen=true;if(location.pathname==='/companies')selectedCompany=j.companies?.[0]?.id||'';}if(current)current=j.cases.find(c=>c.id===current.id)||null;if(selectedCompany&&!data.companies.some(c=>c.id===selectedCompany)){selectedCompany='';companyData=null;}await refreshCompany();const teamToken=new URLSearchParams(location.hash.slice(1)).get('team');incomingTeam=teamToken?(await api('/companies/invitation',{token:teamToken})).team:null;render();}
const badge=s=>`<span class="pill ${s==='approved'?'green':['needs_changes','reviewer_changes','failed'].includes(s)?'amber':''}">${esc(stages[s]||s)}</span>`;
