 const s=current.state,isEmployee=current.is_employee&&(role==='employee'||!current.is_reviewer),canEdit=(isEmployee||current.is_reviewer)&&!!current.employee_joined&&!['processing','deleted','deleting'].includes(s.stage),a=s.analysis;
 $('#title').textContent=s.name;$('#subtitle').textContent=`${current.company_name?current.company_name+' · ':''}${isEmployee?'Employee view':'Reviewer view'}${current.reviewer_name?' · Reviewer: '+current.reviewer_name:''} · Version ${s.version}${s.self_test?' · Self-test with one account':''}`;
