 content.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>showComparison(b.dataset.compare.split(',')));content.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));content.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(confirm('Remove this document from the current version?'))action(()=>api(`/cases/${current.id}/remove-document`,{revision:current.revision,document_id:b.dataset.remove}));});
 bind('upload-form','submit',e=>{e.preventDefault();const file=$('#document-file').files[0],category=$('#document-category').value;if(!file)return;action(async()=>{notice('Preparing document pages. Please keep this tab open.','busy');const pages=await prepare(file);const form=new FormData();form.set('revision',current.revision);form.set('category',category);form.set('file',file);pages.forEach((p,i)=>form.append('pages',p,`page-${i}.jpg`));notice('Uploading private document…','busy');await api(`/cases/${current.id}/documents`,form);},'Preparing upload…');});
