 bind('recover','click',()=>action(()=>api(`/cases/${current.id}/recover`,{revision:current.revision})));bind('ask-reviewer','click',()=>{const message=$('#employee-note').value;action(()=>api(`/cases/${current.id}/ask-reviewer`,{revision:current.revision,message}));});
