 bind('export','click',async()=>{try{const j=await api(`/cases/${current.id}/export`),u=URL.createObjectURL(new Blob([JSON.stringify(j,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`workforce-reviewed-v${s.version}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){notice(e.message,'error');}});
