function analysisHTML(a){const delta=comparison(current.state.history.at(-1)?.analysis?.issues,a.issues);const labels={status:'Reported stay status',stay_expiry:'Reported stay expiry',contract_start:'Proposed work start'};return `<section class="card"><div class="section-head"><h2>Findings & next steps</h2><span class="pill">${a.issues.length} to check</span></div><p class="help">Dates are compared by code. Extracted text and signature observations come from the vision model and require original-page verification.</p>${observationHTML(a)}<div class="facts">${Object.entries(a.reading.fields).map(([k,v])=>`<div class="fact"><small>${esc(labels[k]||k)}</small><strong>${esc(v.value||'Not confirmed')}</strong>${v.provenance==='reviewer'?'<small>Reviewer-corrected · original AI reading retained</small>':''}${v.validation_issue?`<small>Withheld: ${esc(v.validation_issue.replaceAll('_',' '))}</small>`:''}${v.evidence.map(e=>`<div class="quote">${esc(e.quote)}</div><button class="link-button" data-page="${esc(e.page_id)}">View source page</button>`).join('')}</div>`).join('')}</div>${current.state.history.length?`<div class="comparison"><strong>Compared with version ${current.state.history.at(-1).version}</strong><div class="compare-cols"><div>Resolved: ${delta.resolved.length}<ul>${delta.resolved.map(i=>`<li>${esc(issueLabel(i))}</li>`).join('')}</ul></div><div>Remaining: ${delta.remaining.length} · New: ${delta.new.length}${delta.unconfirmed.length?`<p>Could not recheck: ${delta.unconfirmed.length}</p><ul>${delta.unconfirmed.map(i=>`<li>${esc(issueLabel(i))}</li>`).join('')}</ul><small>Required information is now missing or unreadable; this is not resolved.</small>`:''}</div></div></div>`:''}${a.issues.map(i=>`<article class="issue"><span class="pill ${i.owner==='employee'?'amber':''}">${i.owner==='employee'?'Employee action':'Company / reviewer action'}</span><h3>${esc(i.title)}</h3><p>${esc(i.detail)}</p>${i.pages.map(p=>`<button class="link-button" data-page="${esc(p)}">View cited page</button>`).join('')}${new Set(i.pages).size>1?`<button class="secondary" data-compare="${esc([...new Set(i.pages)].join(','))}">Compare source pages</button>`:''}<small>${esc(i.basis)}</small></article>`).join('')||(current.state.stage==='approved'?'<div class="notice">The original documents were reviewed for this version. Read the final preparation message below.</div>':'<div class="notice">No internal preparation issue was detected. The original documents still need a reviewer check.</div>')}<details><summary>Official references</summary><p class="help">Reviewed reference links, not a live legal search or proof of eligibility.</p>${(a.guidance?.sources||[]).map(s=>`<div class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>${esc(s.publisher)} · Reviewed ${esc(s.reviewed_at)}</small><p>${esc(s.summary)}</p></div>`).join('')||'<p class="help">Ask the Immigration Contact Center (1345) about the exact status and procedure.</p>'}</details><details><summary>Read extracted text & AI execution evidence</summary>${a.reading.pages.map(p=>`<details><summary>Page ${esc(p.page_id.split(':')[1])} · ${esc(p.quality)} · signature ${esc(p.signature)}</summary><p class="help">${esc(p.quality_reason||'')}</p><p class="message">${esc(p.text)}</p><button class="link-button" data-page="${esc(p.page_id)}">Compare with image</button></details>`).join('')}${[...(a.reading.proof.batches||[a.reading.proof]),a.guidance?.proof].filter(Boolean).map(p=>`<p class="mini"><strong>${p.mode==='live'?'Actual API response':'Controlled test · not a new AI response'}</strong><br>${esc(p.model)}<br>HTTP ${p.http_status} · ${(p.latency_ms/1000).toFixed(1)}s · ${p.usage?.total_tokens??'?'} tokens<br>${esc(p.response_id)}<br>${esc(p.at)}</p>`).join('')}</details></section>`;}
function issueLabel(id){const prior=current.state.history.at(-1)?.analysis?.issues||[];return prior.find(i=>i.id===id)?.title||({quality:'Document readability'}[id])||id;}
function showPage(id){$('#compare-images').hidden=true;$('#compare-images').innerHTML='';$('#page-image').hidden=false;$('#original-link').hidden=false;const [doc,n]=id.split(':');const d=[...current.state.documents,...current.state.history.flatMap(h=>h.documents)].find(d=>d.id===doc);if(!d)return;$('#viewer-title').textContent=`${categoryName(d.category)} · Page ${n}`;$('#viewer-caption').textContent='This is the rendered page used for AI analysis. Compare any AI transcription with the image and original file.';$('#page-image').src=fileUrl(doc,`page-${Number(n)-1}`);$('#original-link').href=fileUrl(doc,'original');$('#viewer').showModal();}
async function canvasBlob(canvas){for(const quality of [.9,.78,.62,.48]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=UPLOAD_LIMITS.pageBytes)return blob;}throw new Error('This page is too detailed to upload clearly. Use a cleaner scan or a smaller image.');}
async function prepare(file){if(file.size>UPLOAD_LIMITS.fileBytes)throw new Error(errors.too_large);if(!['application/pdf','image/jpeg','image/png'].includes(file.type))throw new Error(errors.unsupported_file);const result=[];if(file.type==='application/pdf'){const pdfjs=await import('/vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';let pdf,loadingTask;try{loadingTask=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,standardFontDataUrl:'/vendor/fonts/',useSystemFonts:true});pdf=await loadingTask.promise;}catch(e){throw new Error(e.name==='PasswordException'?'Unlock this PDF before uploading.':'This PDF could not be opened. Try exporting it again.');}try{if(pdf.numPages>UPLOAD_LIMITS.pagesPerFile)throw new Error(errors.page_limit);for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),v=p.getViewport({scale:1});const scale=Math.min(1800/Math.max(v.width,v.height),2.5),viewport=p.getViewport({scale});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await p.render({canvasContext:canvas.getContext('2d'),viewport}).promise;result.push(await canvasBlob(canvas));canvas.width=canvas.height=0;}}finally{await loadingTask.destroy();}}else{let img;try{img=await createImageBitmap(file);}catch{throw new Error('This image could not be opened. Use a JPEG or PNG export.');}try{if(img.width<80||img.height<80)throw new Error('This image is too small to read. Upload a larger photo.');const scale=Math.min(1,1800/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);result.push(await canvasBlob(canvas));}finally{img.close();}}return result;}
function canLeave(){if(busy)return false;if(dirty&&!confirm('Discard your unsaved changes?'))return false;dirty=false;return true;}
$('#company-nav').onclick=e=>{if(!canLeave())e.preventDefault();};$('#home').onclick=()=>{if(canLeave()){location.href='/employee';}};$('#refresh').onclick=()=>{if(canLeave())action(load,'Refreshing…');};$('#close-viewer').onclick=()=>$('#viewer').close();window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
