 const displayMissing=[...(companyMissing.length?[{id:'company',title:`Record company verification (${companyMissing.length} checks)`}]:[]),...(profileMissing.length?[{id:'status',title:`Complete your situation (${profileMissing.length} answers)`}]:[]),...missing.filter(t=>!profileIDs.includes(t.id)&&!['company','previous-employment','procedure'].includes(t.id))];
